    #[ensures(forall(|i: usize| i < numbers.len() ==> result[i] == max_prefix(numbers, i)))]
    let mut result = Vec::with_capacity(numbers.len());
    let mut current_max = i32::MIN; // Initialize to the smallest possible i32 value

    // Invariant: At the start of each iteration, current_max is the maximum of the first i elements of numbers
    // and result contains the maximums for the first i elements.
    #[invariant(0 <= i && i <= numbers.len())]
